B.aDN=new A.a("\u0627\u0644\u062a\u0623\u0646\u064a \u0648\u0627\u0644\u062a\u0631\u064a\u062b \u0641\u064a \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629: \u062d\u064a\u062b \u062a\u0623\u0646\u0649 \u0623\u0628\u0648 \u0630\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0644\u0645\u0627 \u064a\u0639\u0631\u0641\u0647 \u0645\u0646 \u0643\u0631\u0627\u0647\u064a\u0629 \u0642\u0631\u064a\u0634 \u0644\u0643\u0644 \u0645\u0646 \u064a\u062e\u0627\u0637\u0628 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u062a\u0623\u0646\u064a \u062a\u0635\u0631\u0641 \u0623\u0645\u0646\u064a \u062a\u0642\u062a\u0636\u064a\u0647 \u062d\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u0645\u0648\u0642\u0641\u060c \u0641\u0644\u0648 \u0633\u0623\u0644 \u0639\u0646\u0647 \u0644\u0639\u0644\u0645\u062a \u0628\u0647 \u0642\u0631\u064a\u0634\u060c \u0648\u0628\u0627\u0644\u062a\u0627\u0644\u064a \u0642\u062f \u064a\u062a\u0639\u0631\u0636 \u0644\u0644\u0623\u0630\u0649 \u0648\u0627\u0644\u0637\u0631\u062f\u060c \u0648\u064a\u062e\u0633\u0631 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0647\u062f\u0641\u0647\u060c \u0627\u0644\u0630\u064a \u0645\u0646 \u0623\u062c\u0644\u0647 \u062a\u0631\u0643 \u0645\u0636\u0627\u0631\u0628 \u0642\u0648\u0645\u0647\u060c \u0648\u062a\u062d\u0645\u0644 \u0641\u064a \u0633\u0628\u064a\u0644\u0647 \u0645\u0635\u0627\u0639\u0628 \u0648\u0645\u0634\u0627\u0642 \u0627\u0644\u0633\u0641\u0631.",null)
B.aGN=new A.a("\u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0637 \u0648\u0627\u0644\u062d\u0630\u0631 \u0642\u0628\u0644 \u0627\u0644\u0646\u0637\u0642 \u0628\u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629: \u062d\u064a\u0646 \u0633\u0623\u0644 \u0639\u0644\u064a \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0623\u0628\u0627 \u0630\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0639\u0646 \u0623\u0645\u0631\u0647 \u0648\u0633\u0628\u0628 \u0645\u062c\u064a\u0626\u0647 \u0625\u0644\u0649 \u0645\u0643\u0629\u060c \u0644\u0645 \u064a\u062e\u0628\u0631\u0647 \u0628\u0627\u0644\u0631\u063a\u0645 \u0645\u0646 \u0623\u0646\u0647 \u0627\u0633\u062a\u0636\u0627\u0641\u0647 \u062b\u0644\u0627\u062b\u0629 \u0623\u064a\u0627\u0645\u060c \u0625\u0645\u0639\u0627\u0646\u064b\u0627 \u0641\u064a \u0627\u0644\u062d\u0630\u0631\u060c \u0641\u0627\u0634\u062a\u0631\u0637 \u0639\u0644\u064a\u0647 \u0642\u0628\u0644 \u0623\u0646 \u064a\u062e\u0628\u0631\u0647 \u0623\u0646 \u064a\u0643\u062a\u0645 \u0639\u0646\u0647\u060c \u0648\u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0630\u0627\u062a\u0647 \u0623\u0646 \u064a\u0631\u0634\u062f\u0647 \u0641\u0647\u0630\u0627 \u063a\u0627\u064a\u0629 \u0641\u064a \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0637\u060c \u0648\u062a\u0645 \u0645\u0627 \u0623\u0631\u0627\u062f\u0647.",null)
