B.aDv=new A.a("\u062a\u0639\u062a\u0628\u0631 \u0647\u0630\u0647 \u0627\u0644\u0645\u0639\u0627\u0647\u062f\u0629 \u0623\u0633\u0627\u0633\u0627\u064b \u0644\u0644\u0645\u0639\u0627\u0647\u062f\u0627\u062a \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a\u0629 \u0648\u0646\u0645\u0648\u0630\u062c\u0627\u064b \u0641\u0631\u064a\u062f\u0627\u064b \u0644\u0644\u0645\u0639\u0627\u0647\u062f\u0627\u062a \u0627\u0644\u062f\u0648\u0644\u064a\u0629\u060c \u0628\u0645\u0627 \u0633\u0628\u0642\u0647\u0627 \u0645\u0646 \u0645\u0641\u0627\u0648\u0636\u0627\u062a \u0648\u0645\u0627\u062d\u0648\u062a\u0647 \u0645\u0646 \u0634\u0631\u0648\u0637 \u0648\u0645\u0627\u062a\u0645\u062b\u0644 \u0628\u0647\u0627 \u0645\u0646 \u062e\u0644\u0642 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u064a \u0627\u0644\u0646\u0632\u0648\u0644 \u0639\u0646\u062f \u0631\u0636\u0627 \u0627\u0644\u0637\u0631\u0641 \u0627\u0644\u0622\u062e\u0631\u060c \u0648\u0641\u064a \u0643\u064a\u0641\u064a\u0629 \u0627\u0644\u0635\u064a\u0627\u063a\u0629 \u0648\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0647\u0630\u0647 \u0627\u0644\u0645\u0639\u0627\u0647\u062f\u0629\u060c \u0633\u0628\u0642\u0647\u0627 \u0645\u0641\u0627\u0648\u0636\u0627\u062a \u0645\u0646 \u0642\u0628\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0648\u0641\u0634\u0644 \u0628\u0639\u0636 \u0627\u0644\u0645\u0645\u062b\u0644\u064a\u0646 \u0641\u064a \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u062a\u0641\u0627\u0642\u060c \u0648\u062f\u0627\u0631\u062a \u0645\u0634\u0627\u0648\u0631\u0627\u062a \u0634\u062a\u0649 \u0645\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0642\u0628\u0644 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u062d\u062a\u0649 \u062a\u0648\u0635\u0644 \u0627\u0644\u0641\u0631\u064a\u0642\u0627\u0646 \u0625\u0644\u0649 \u0627\u062a\u0641\u0627\u0642 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u0645\u062b\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0633\u0647\u064a\u0644 \u0628\u0646 \u0639\u0645\u0631\u0648 \u0648\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0644\u0649 \u0645\u0644\u0623 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646.",null)
B.aHY=new A.a("\u0648\u0642\u062f \u0639\u0642\u062f\u062a \u0647\u0630\u0647 \u0627\u0644\u0645\u0639\u0627\u0647\u062f\u0629 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0641\u064a\u0647 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0628\u0645\u0631\u0643\u0632 \u0627\u0644\u0642\u0648\u0629 \u0644\u0627 \u0627\u0644\u0636\u0639\u0641\u060c \u0648\u0643\u0627\u0646 \u0628\u0627\u0633\u062a\u0637\u0627\u0639\u062a\u0647\u0645 \u0623\u0646 \u0644\u0627\u064a\u0642\u0628\u0644\u0648\u0627 \u0634\u0631\u0648\u0637\u0647\u0627 \u0627\u0644\u062a\u064a \u0627\u063a\u062a\u0627\u0638 \u0645\u0646\u0647\u0627 \u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u0629\u060c \u0648\u0644\u0643\u0646 \u0645\u0627\u0643\u0627\u0646 \u0644\u0647\u0645 \u0623\u0646 \u064a\u062e\u0631\u062c\u0648\u0627 \u0639\u0646 \u0637\u0648\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0630\u064a \u0644\u0627\u064a\u0646\u0637\u0642 \u0639\u0646 \u0627\u0644\u0647\u0648\u0649\u060c \u0648\u0642\u062f \u062a\u0645\u0627\u062f\u0649 \u0631\u0633\u0648\u0644 \u0642\u0631\u064a\u0634 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0641\u064a \u0645\u0641\u0627\u0648\u0636\u062a\u0647 \u0648\u0643\u0627\u0646 \u0641\u0631\u062f\u0627\u064b \u0628\u064a\u0646 \u062c\u064a\u0634 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0641\u0644\u0645 \u064a\u0646\u0644\u0647 \u0623\u0630\u0649\u060c \u0648\u0644\u0645 \u064a\u062a\u0645\u0627\u062f\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0628\u0627\u0644\u0642\u062a\u0644 \u0644\u0623\u0646 \u0627\u0644\u0633\u0641\u0631\u0627\u0621 \u0644\u0627\u062a\u0642\u062a\u0644 \u0648\u0644\u0643\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u064a\u0631\u0636\u064a\u0647\u060c \u0648\u064a\u0633\u0639\u0647 \u0628\u0627\u0644\u062d\u0644\u0645 \u0648\u0627\u0644\u0644\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0644 \u0625\u0644\u0649 \u0627\u0644\u063a\u0627\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u0646\u0634\u062f\u0647\u0627 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0647\u064a \u062d\u0642\u0646 \u0627\u0644\u062f\u0645\u0627\u0621 \u0648\u0627\u062d\u0644\u0627\u0644 \u0627\u0644\u0633\u0644\u0627\u0645 \u0648\u0631\u062c\u0627\u0621 \u0623\u0646 \u064a\u0639\u0642\u0644 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u062d\u0642\u060c \u0648\u0623\u0646 \u064a\u0631\u0627\u062c\u0639\u0648\u0627 \u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u0648\u064a\u0633\u0645\u0639\u0648\u0627 \u0643\u0644\u0627\u0645 \u0627\u0644\u0644\u0647 \u0648\u062a\u062f\u062e\u0644 \u0627\u0644\u062f\u0639\u0648\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a\u0629 \u0637\u0648\u0631\u0627\u064b \u062c\u062f\u064a\u062f\u0627\u064b \u0628\u0635\u0648\u0631 \u0623\u062e\u0631\u0649 \u0641\u064a \u0627\u0644\u0627\u0646\u062a\u0634\u0627\u0631 \u0648\u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u0646\u0627\u0633.",null)
