B.aOl=new A.a("\u0628\u0644\u063a \u0623\u0628\u0627 \u0633\u0641\u064a\u0627\u0646 \u062e\u0628\u0631 \u0645\u0633\u064a\u0631 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0623\u0635\u062d\u0627\u0628\u0647 \u0645\u0646 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0628\u0642\u0635\u062f \u0627\u0639\u062a\u0631\u0627\u0636 \u0642\u0627\u0641\u0644\u062a\u0647 \u0648\u0627\u062d\u062a\u0648\u0627\u0626\u0647\u0627 \u0641\u0628\u0627\u062f\u0631 \u0627\u0644\u0649 \u062a\u062d\u0648\u064a\u0644 \u0645\u0633\u0627\u0631\u0647\u0627 \u0627\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0627\u062d\u0644\u060c \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a \u0623\u0631\u0633\u0644 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0636\u0645\u0636\u0645 \u0627\u0644\u063a\u0641\u0627\u0631\u064a \u0627\u0644\u0649 \u0642\u0631\u064a\u0634 \u064a\u0633\u062a\u0646\u0641\u0631\u0647\u0627 \u0644\u0625\u0646\u0642\u0627\u0630 \u0642\u0627\u0641\u0644\u062a\u0647\u0627 \u0648\u0623\u0645\u0648\u0627\u0644\u0647\u0627 \u0641\u0642\u062f \u0643\u0627\u0646 \u0623\u0628\u0648 \u0633\u0641\u064a\u0627\u0646 \u064a\u0642\u0638\u0627\u064b \u062d\u0630\u0631\u0627\u064b \u064a\u062a\u0644\u0642\u0637 \u0623\u062e\u0628\u0627\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u064a\u0633\u0623\u0644 \u0639\u0646 \u062a\u062d\u0631\u0643\u0627\u062a\u0647\u0645 \u0628\u0644 \u064a\u062a\u062d\u0633\u0633 \u0623\u062e\u0628\u0627\u0631\u0647\u0645 \u0628\u0646\u0641\u0633\u0647\u060c \u0641\u0642\u062f \u062a\u0642\u062f\u0645 \u0627\u0644\u0649 \u0628\u062f\u0631 \u0628\u0646\u0641\u0633\u0647 \u0648\u0633\u0623\u0644 \u0645\u0646 \u0643\u0627\u0646 \u0647\u0646\u0627\u0643 \u0647\u0644 \u0631\u0623\u064a\u062a\u0645 \u0645\u0646 \u0623\u062d\u062f\u061f \u0642\u0627\u0644\u0648\u0627: \u0644\u0627 \u0625\u0644\u0627 \u0631\u062c\u0644\u064a\u0646 \u0642\u0627\u0644: \u0627\u0631\u0648\u0646\u064a \u0645\u0646\u0627\u062e \u0631\u0643\u0627\u0628\u0647\u0645\u0627 \u0641\u0623\u0631\u0648\u0647\u060c \u0641\u0623\u062e\u0630 \u0627\u0644\u0628\u0639\u0631 \u0641\u0641\u062a\u0647 \u0641\u0625\u0630\u0627 \u0647\u0648 \u0641\u064a\u0647 \u0627\u0644\u0646\u0648\u0649 \u0641\u0642\u0627\u0644: \u0647\u0630\u0627 \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u0627\u0626\u0641 \u064a\u062b\u0631\u0628 \u0641\u0642\u062f \u0627\u0633\u062a\u0637\u0627\u0639 \u0623\u0646 \u064a\u0639\u0631\u0641 \u062a\u062d\u0631\u0643\u0627\u062a \u0639\u062f\u0648\u0647 \u062d\u062a\u0649 \u062e\u0628\u0631 \u0627\u0644\u0633\u0631\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0637\u0644\u0627\u0639\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u063a\u0630\u0627\u0621 \u062f\u0648\u0627\u0628\u0647\u0627 \u0628\u0641\u062d\u0635\u0647 \u0627\u0644\u0628\u0639\u0631 \u0627\u0644\u0630\u064a \u062e\u0644\u0641\u062a\u0647 \u0627\u0644\u0627\u0628\u0644\u060c \u0625\u0630 \u0639\u0631\u0641 \u0623\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0623\u064a \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0628\u0627\u0644\u062a\u0627\u0644\u064a \u0641\u0642\u0627\u0641\u0644\u062a\u0647 \u0641\u064a \u062e\u0637\u0631 \u0641\u0623\u0631\u0633\u0644 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0636\u0645\u0636\u0645 \u0627\u0644\u0649 \u0642\u0631\u064a\u0634 \u0648\u063a\u064a\u0631 \u0637\u0631\u064a\u0642 \u0627\u0644\u0642\u0627\u0641\u0644\u0629 \u0648\u0627\u062a\u062c\u0647 \u0646\u062d\u0648 \u0633\u0627\u062d\u0644 \u0627\u0644\u0628\u062d\u0631.",null)
B.avR=new A.a("\u0643\u0627\u0646 \u0648\u0642\u0639 \u062e\u0628\u0631 \u0627\u0644\u0642\u0627\u0641\u0644\u0629 \u0634\u062f\u064a\u062f\u0627\u064b \u0639\u0644\u0649 \u0642\u0631\u064a\u0634 \u0641\u0642\u062f \u062c\u0627\u0621\u0647\u0645 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0636\u0645\u0636\u0645 \u0627\u0644\u063a\u0641\u0627\u0631\u064a \u0628\u0635\u0648\u0631\u0629 \u0645\u062b\u064a\u0631\u0629 \u062c\u062f\u0627\u064b \u064a\u062a\u0623\u062b\u0631 \u0628\u0647\u0627 \u0643\u0644 \u0645\u0646 \u0631\u0622\u0647\u0627 \u0623\u0648 \u0633\u0645\u0639 \u0628\u0647\u0627 \u0625\u0630 \u062c\u0627\u0621\u0647\u0645 \u0648\u0642\u062f \u062d\u0648\u0644 \u0631\u062d\u0644\u0647 \u0648\u062c\u062f\u0639 \u0623\u0646\u0641 \u0628\u0639\u064a\u0631\u0647 \u0648\u0634\u0642 \u0642\u0645\u064a\u0635\u0647 \u0645\u0646 \u0642\u0628\u0644 \u0648\u0645\u0646 \u062f\u0628\u0631 \u0648\u062f\u062e\u0644 \u0645\u0643\u0629 \u0648\u0647\u0648 \u064a\u0646\u0627\u062f\u064a \u0628\u0623\u0639\u0644\u0649 \u0635\u0648\u062a\u0647: \u064a\u0627\u0645\u0639\u0634\u0631 \u0642\u0631\u064a\u0634 \u0627\u0644\u0644\u0637\u064a\u0645\u0629 \u0627\u0644\u0644\u0637\u064a\u0645\u0629 \u0623\u0645\u0648\u0627\u0644\u0643\u0645 \u0645\u0639 \u0623\u0628\u064a \u0633\u0641\u064a\u0627\u0646 \u0642\u062f \u0639\u0631\u0636 \u0644\u0647\u0627 \u0645\u062d\u0645\u062f \u0641\u064a \u0623\u0635\u062d\u0627\u0628\u0647 \u0644\u0627 \u0623\u0631\u0649 \u0623\u0646 \u062a\u062f\u0631\u0643\u0648\u0647\u0627 \u0627\u0644\u063a\u0648\u062b \u0627\u0644\u063a\u0648\u062b.",null)
