B.aE8=new A.a("\u0646\u0638\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u062c\u0646\u062f\u0647 \u0628\u0639\u062f \u0623\u0646 \u0631\u0623\u0649 \u0637\u0627\u0639\u0629 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0648\u0634\u062c\u0627\u0639\u062a\u0647\u0645 \u0648\u0627\u062c\u062a\u0645\u0627\u0639\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0642\u062a\u0627\u0644 \u0648\u0639\u0642\u062f \u0627\u0644\u0644\u0648\u0627\u0621 \u0627\u0644\u0623\u0628\u064a\u0636 \u0648\u0633\u0644\u0651\u0645\u0629 \u0627\u0644\u0649 \u0645\u0635\u0639\u0628 \u0628\u0646 \u0639\u0645\u064a\u0631 \u0648\u0623\u0639\u0637\u0649 \u0631\u0627\u064a\u062a\u064a\u0646 \u0633\u0648\u062f\u0627\u0648\u064a\u0646 \u0627\u0644\u0649 \u0633\u0639\u062f \u0628\u0646 \u0645\u0639\u0627\u0630 \u0648\u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0648\u062c\u0639\u0644 \u0639\u0644\u0649 \u0627\u0644\u0633\u0627\u0642\u0629 \u0642\u064a\u0633 \u0628\u0646 \u0623\u0628\u064a \u0635\u0639\u0635\u0639\u0629.",null)
B.ayO=new A.a("\u0648\u0642\u0627\u0645 \ufdfa \u0648\u0645\u0639\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631 \u064a\u0633\u062a\u0643\u0634\u0641 \u0623\u062d\u0648\u0627\u0644 \u062c\u064a\u0634 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0648\u0628\u064a\u0646\u0645\u0627 \u0647\u0645\u0627 \u064a\u062a\u062c\u0648\u0644\u0627\u0646 \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0644\u0642\u064a\u0627 \u0634\u064a\u062e\u0627\u064b \u0645\u0646 \u0627\u0644\u0639\u0631\u0628\u060c \u0641\u0633\u0623\u0644\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0646 \u062c\u064a\u0634 \u0642\u0631\u064a\u0634 \u0648\u0639\u0646 \u0645\u062d\u0645\u062f \u0648\u0623\u0635\u062d\u0627\u0628\u0647 \u0648\u0645\u0627\u0628\u0644\u063a\u0647 \ufdfa \u0645\u0646 \u0623\u062e\u0628\u0627\u0631\u0647\u0645: \u0641\u0642\u0627\u0644 \u0627\u0644\u0634\u064a\u062e \u0644\u0627 \u0623\u062e\u0628\u0631\u0643\u0645\u0627 \u062d\u062a\u0649 \u062a\u062e\u0628\u0631\u0627\u0646\u064a \u0645\u0645\u0646 \u0623\u0646\u062a\u0645\u0627\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0625\u0630\u0627 \u0623\u062e\u0628\u0631\u062a\u0646\u0627 \u0623\u062e\u0628\u0631\u0646\u0627\u0643 \u0641\u0642\u0627\u0644: \u0623\u0648 \u0630\u0627\u0643 \u0628\u0630\u0627\u0643\u061f \u0642\u0627\u0644: \u0646\u0639\u0645\u060c \u0641\u0642\u0627\u0644 \u0627\u0644\u0634\u064a\u062e : \u0641\u0625\u0646\u0647 \u0628\u0644\u063a\u0646\u064a \u0623\u0646 \u0645\u062d\u0645\u062f\u0627\u064b \u0648\u0623\u0635\u062d\u0627\u0628\u0647 \u062e\u0631\u062c\u0648\u0627 \u064a\u0648\u0645 \u0643\u0630\u0627 \u0648\u0643\u0630\u0627 \u0641\u0625\u0646 \u0643\u0627\u0646 \u0635\u062f\u0642 \u0627\u0644\u0630\u064a \u0623\u062e\u0628\u0631\u0646\u064a \u0641\u0647\u0645 \u0627\u0644\u064a\u0648\u0645 \u0628\u0645\u0643\u0627\u0646 \u0643\u0630\u0627 \u0648\u0643\u0630\u0627 -\u0644\u0644\u0645\u0643\u0627\u0646 \u0627\u0644\u0630\u064a \u0628\u0647 \u062c\u064a\u0634 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646- \u0648\u0628\u0644\u063a\u0646\u064a \u0623\u0646 \u0642\u0631\u064a\u0634\u0627\u064b \u062e\u0631\u062c\u0648\u0627 \u064a\u0648\u0645 \u0643\u0630\u0627 \u0648\u0643\u0630\u0627 \u0641\u0625\u0646 \u0643\u0627\u0646 \u0635\u062f\u0642 \u0627\u0644\u0630\u064a \u0623\u062e\u0628\u0631\u0646\u064a \u0641\u0647\u0645 \u0627\u0644\u064a\u0648\u0645 \u0628\u0645\u0643\u0627\u0646 \u0643\u0630\u0627 \u0648\u0643\u0630\u0627 -\u0644\u0644\u0645\u0643\u0627\u0646 \u0627\u0644\u0630\u064a \u0641\u064a\u0647 \u062c\u064a\u0634 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u0639\u0644\u0627\u064b- \u062b\u0645 \u0642\u0627\u0644 \u0627\u0644\u0634\u064a\u062e: \u0644\u0642\u062f \u0623 \u062e\u0628\u0631\u062a\u0643\u0645\u0627 \u0639\u0645\u0627 \u0623\u0631\u062f\u062a\u0645\u0627 \u0641\u0623\u062e\u0628\u0631\u0627\u0646\u064a: \u0645\u0645\u0646 \u0623\u0646\u062a\u0645\u0627\u061f \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0646\u062d\u0646 \u0645\u0646 \u0645\u0627\u0621 \u060c \u062b\u0645 \u0627\u0646\u0635\u0631\u0641 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0623\u0628\u0648\u0628\u0643\u0631 \u0639\u0646 \u0627\u0644\u0634\u064a\u062e \u0648\u0628\u0642\u064a \u0647\u0630\u0627 \u0627\u0644\u0634\u064a\u062e \u064a\u0642\u0648\u0644: \u0645\u0627\u0645\u0646 \u0645\u0627\u0621\u061f \u0623\u0645\u0646 \u0645\u0627\u0621 \u0627\u0644\u0639\u0631\u0627\u0642.",null)
