B.aXL=new A.a("\u0644\u0645\u0627 \u0648\u0635\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0639\u0633\u0641\u0627\u0646 \u0644\u0642\u064a\u0647 \u0628\u0634\u0631 \u0628\u0646 \u0633\u0641\u064a\u0627\u0646 \u0627\u0644\u0643\u0639\u0628\u064a \u0627\u0644\u062e\u0632\u0627\u0639\u064a \u0641\u0642\u0627\u0644: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0647\u0630\u0647 \u0642\u0631\u064a\u0634 \u0642\u062f \u0633\u0645\u0639\u062a \u0628\u0645\u0633\u064a\u0631\u0643 \u0648\u0645\u0639\u0647\u0627 \u0627\u0644\u0639\u0648\u0630 \u0627\u0644\u0645\u0637\u0627\u0641\u064a\u0644\u060c \u0642\u062f \u0644\u0628\u0633\u0648\u0627 \u062c\u0644\u0648\u062f \u0627\u0644\u0646\u0645\u0648\u0631 \u064a\u0639\u0627\u0647\u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0623\u0644\u0627 \u062a\u062f\u062e\u0644\u0647\u0627 \u0639\u0644\u064a\u0647\u0645 \u0639\u0646\u0648\u0629 \u0623\u0628\u062f\u0627\u064b\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u064a\u0627\u0648\u064a\u062d \u0642\u0631\u064a\u0634 \u0644\u0642\u062f \u0623\u0643\u0644\u062a\u0647\u0645 \u0627\u0644\u062d\u0631\u0628 \u0645\u0627\u0630\u0627 \u0639\u0644\u064a\u0647\u0645 \u0644\u0648 \u062e\u0644\u0648\u0627 \u0628\u064a\u0646\u064a \u0648\u0628\u064a\u0646 \u0633\u0627\u0626\u0631 \u0627\u0644\u0646\u0627\u0633\u061f \u0641\u0625\u0646 \u0623\u0635\u0627\u0628\u0648\u0646\u064a \u0643\u0627\u0646 \u0627\u0644\u0630\u064a \u0623\u0631\u0627\u062f\u0648\u0627 \u0648\u0625\u0646 \u0623\u0638\u0647\u0631\u0646\u064a \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u062f\u062e\u0644\u0648\u0627 \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0647\u0645 \u0648\u0627\u0641\u0631\u0648\u0646\u060c \u0648\u0625\u0646 \u0644\u0645 \u064a\u0641\u0639\u0644\u0648\u0627 \u0642\u0627\u062a\u0644\u0648\u0627 \u0648\u0628\u0647\u0645 \u0642\u0648\u0629 \u0641\u0645\u0627\u0630\u0627 \u062a\u0638\u0646 \u0642\u0631\u064a\u0634\u061f \u0648\u0627\u0644\u0644\u0647 \u0625\u0646\u064a \u0644\u0627\u0623\u0632\u0627\u0644 \u0623\u062c\u0627\u0647\u062f\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a \u0628\u0639\u062b\u0646\u064a \u0627\u0644\u0644\u0647 \u0644\u0647 \u0623\u0648 \u062a\u0646\u0641\u0631\u062f \u0647\u0630\u0647 \u0627\u0644\u0633\u0627\u0644\u0641\u0629.",null)
B.aD0=new A.a("\u0648\u0642\u062f \u0627\u0633\u062a\u0634\u0627\u0631 \ufdfa \u0623\u0635\u062d\u0627\u0628\u0647 \u0644\u0645\u0627 \u0628\u0644\u063a\u0647 \u062e\u0628\u0631 \u0627\u0633\u062a\u0639\u062f\u0627\u062f \u0642\u0631\u064a\u0634 \u0644\u0635\u062f\u0647 \u0639\u0646 \u062f\u062e\u0648\u0644 \u0627\u0644\u0628\u064a\u062a \u0627\u0644\u062d\u0631\u0627\u0645 \u0648\u0639\u0631\u0636 \ufdfa \u0639\u0644\u0649 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0627\u0644\u0645\u0634\u0648\u0631\u0629 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0639\u0644\u0649 \u0631\u0623\u064a\u064a\u0646\u060c \u0627\u0644\u0627\u0648\u0644 : \u0627\u0644\u0645\u064a\u0644 \u0625\u0644\u0649 \u0639\u064a\u0627\u0644 \u0648\u0630\u0631\u0627\u0631\u064a \u0627\u0644\u0623\u062d\u0627\u0628\u064a\u0634 \u0627\u0644\u0630\u064a\u0646 \u062e\u0631\u062c\u0648\u0627 \u0644\u0645\u0639\u0627\u0648\u0646\u0629 \u0642\u0631\u064a\u0634\u060c \u0627\u0644\u062b\u0627\u0646\u0649 : \u0642\u0635\u062f \u0627\u0644\u0628\u064a\u062a \u0627\u0644\u062d\u0631\u0627\u0645 \u0641\u0645\u0646 \u0635\u062f\u0651\u0647 \u0639\u0646\u0647 \u0642\u0627\u062a\u0644\u0647 \u062d\u062a\u0649 \u064a\u062a\u0645\u0643\u0646 \u0645\u0646 \u062a\u062d\u0642\u064a\u0642 \u0647\u062f\u0641\u0647.",null)
B.aQD=new A.a("\u0648\u0644\u0645\u0627 \u0639\u0631\u0636 \ufdfa \u0627\u0644\u0645\u0634\u0648\u0631\u0629 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0639\u0644\u0649 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u062a\u0642\u062f\u0645 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642 \u0628\u0631\u0623\u064a\u0647 \u0627\u0644\u0630\u064a \u062a\u062f\u0639\u0645\u0647 \u0627\u0644\u062d\u062c\u0629 \u0627\u0644\u0648\u0627\u0636\u062d\u0629\u060c \u062d\u064a\u062b \u0623\u0634\u0627\u0631 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u062a\u0631\u0643 \u0642\u062a\u0627\u0644\u0647\u0645 \u0648\u0627\u0644\u0627\u0633\u062a\u0645\u0631\u0627\u0631 \u0639\u0644\u0649 \u0645\u0627\u062e\u0631\u062c \u0644\u0647 \u0645\u0646 \u0623\u062f\u0627\u0621 \u0627\u0644\u0639\u0645\u0631\u0629 \u062d\u062a\u0649 \u064a\u0643\u0648\u0646 \u0628\u062f\u0621 \u0627\u0644\u0642\u062a\u0627\u0644 \u0645\u0646\u0647\u0645\u060c \u0641\u0627\u0633\u062a\u062d\u0633\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0647\u0630\u0627 \u0627\u0644\u0631\u0623\u064a \u0648\u0623\u062e\u0630 \u0628\u0647 \u0648\u0623\u0645\u0631 \u0627\u0644\u0646\u0627\u0633 \u0623\u0646 \u064a\u0645\u0636\u0648\u0627 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0633\u0628\u064a\u0644\u060c \u0648\u0639\u0646\u062f\u0645\u0627 \u0627\u0642\u062a\u0631\u0628\u062a \u062e\u064a\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0635\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0623\u0635\u062d\u0627\u0628\u0647 \u0635\u0644\u0627\u0629 \u0627\u0644\u062e\u0648\u0641 \u0628\u0639\u0633\u0641\u0627\u0646.",null)
