B.aZW=new A.a("\u0648\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u0642\u064a\u0645: \u0625\u0646 \u063a\u0632\u0648\u0629 \u0623\u062d\u062f \u0643\u0627\u0646\u062a \u0645\u0642\u062f\u0645\u0629 \u0648\u0625\u0631\u0647\u0627\u0635\u0627\u064b \u0628\u064a\u0646 \u064a\u062f\u064a \u0645\u0648\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0641\u062b\u0628\u062a\u0647\u0645 \u0648\u0648\u0628\u062e\u0647\u0645 \u0639\u0644\u0649 \u0627\u0646\u0642\u0644\u0627\u0628\u0647\u0645 \u0639\u0644\u0649 \u0623\u0639\u0642\u0627\u0628\u0647\u0645 \u0625\u0646 \u0645\u0627\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0648 \u0642\u062a\u0644\u060c \u0628\u0644 \u0627\u0644\u0648\u0627\u062c\u0628 \u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0623\u0646 \u064a\u062b\u0628\u062a\u0648\u0627 \u0639\u0644\u0649 \u062f\u064a\u0646\u0647 \u0648\u062a\u0648\u062d\u064a\u062f\u0647 \u0648\u064a\u0645\u0648\u062a\u0648\u0627 \u0639\u0644\u064a\u0647 \u0623\u0648 \u064a\u0642\u062a\u0644\u0648\u0627 \u0641\u0625\u0646\u0647\u0645 \u0625\u0646\u0645\u0627 \u064a\u0639\u0628\u062f\u0648\u0646 \u0631\u0628 \u0645\u062d\u0645\u062f \u0648\u0647\u0648 \u0644\u0627\u064a\u0645\u0648\u062a \u0641\u0644\u0648 \u0645\u0627\u062a \u0645\u062d\u0645\u062f \u0623\u0648 \u0642\u062a\u0644 \u0644\u0627\u064a\u0646\u0628\u063a\u064a \u0644\u0647\u0645 \u0623\u0646 \u064a\u0635\u0631\u0641\u0647\u0645 \u0630\u0644\u0643 \u0639\u0646 \u062f\u064a\u0646\u0647 \u0648\u0645\u0627\u062c\u0627\u0621 \u0628\u0647 \u0641\u0643\u0644 \u0646\u0641\u0633 \u0630\u0627\u0626\u0642\u0629 \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u0645\u0627\u0646\u064f\u0639\u062a\u064e \u0645\u062d\u0645\u062f \ufdfa \u0644\u064a\u062e\u0644\u0651\u064e\u062f \u0644\u0627\u0647\u0648 \u0648\u0644\u0627\u0647\u0645 \u0628\u0644 \u0644\u064a\u0645\u0648\u062a\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0627\u0644\u062a\u0648\u062d\u064a\u062f.",null)
B.awR=new A.a("\u0648\u0639\u0646 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644:\u0623\u0646 \u0623\u0628\u0627 \u0628\u0643\u0631 \u062e\u0631\u062c \u0648\u0639\u0645\u0631 \u064a\u0643\u0644\u0645 \u0627\u0644\u0646\u0627\u0633 \u0641\u0642\u0627\u0644: \u0627\u062c\u0644\u0633 \u064a\u0627\u0639\u0645\u0631 \u0641\u0623\u0628\u0649 \u0639\u0645\u0631 \u0623\u0646 \u064a\u062c\u0644\u0633 \u0641\u0623\u0642\u0628\u0644 \u0627\u0644\u0646\u0627\u0633 \u0625\u0644\u064a\u0647 \u0648\u062a\u0631\u0643\u0648\u0627 \u0639\u0645\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631 : \u0623\u0645\u0627 \u0628\u0639\u062f \u0645\u0646 \u0643\u0627\u0646 \u064a\u0639\u0628\u062f \u0645\u062d\u0645\u062f\u0627\u064b \u0641\u0625\u0646 \u0645\u062d\u0645\u062f\u0627\u064b \u0642\u062f \u0645\u0627\u062a \u0648\u0645\u0646 \u0643\u0627\u0646 \u064a\u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062d\u064a \u0644\u0627\u064a\u0645\u0648\u062a\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u0648\u064e\u0645\u064e\u0627 \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064c \u0625\u0650\u0644\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0623\u064e\u0641\u064e\u0625\u0650\u0646\u0652 \u0645\u064e\u0627\u062a\u064e \u0623\u064e\u0648\u0652 \u0642\u064f\u062a\u0650\u0644\u064e \u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0639\u0652\u0642\u064e\u0627\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u0652 \u0639\u064e\u0644\u064e\u0649 \u0639\u064e\u0642\u0650\u0628\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u0636\u064f\u0631\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0633\u064e\u064a\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e \u0633\u0648\u0631\u0629 \u0622\u0644 \u0639\u0645\u0631\u0627\u0646 \u060c\u0648\u0642\u0627\u0644: \u0648\u0627\u0644\u0644\u0647 \u0644\u0643\u0623\u0646 \u0627\u0644\u0646\u0627\u0633 \u0644\u0645 \u064a\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0623\u0646\u0632\u0644 \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u062d\u062a\u0649 \u062a\u0644\u0627\u0647\u0627 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0641\u062a\u0644\u0642\u0627\u0647\u0627 \u0645\u0646\u0647 \u0627\u0644\u0646\u0627\u0633 \u0643\u0644\u0647\u0645 \u0641\u0645\u0627 \u0623\u0633\u0645\u0639 \u0628\u0634\u0631\u0627\u064b \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0625\u0644\u0627 \u064a\u062a\u0644\u0648\u0647\u0627\u060c \u0641\u0623\u062e\u0628\u0631\u0646\u064a \u0633\u0639\u064a\u062f \u0628\u0646 \u0627\u0644\u0645\u0633\u064a\u0628 \u0623\u0646 \u0639\u0645\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644: \u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u0647\u0648 \u0625\u0644\u0627 \u0623\u0646 \u0633\u0645\u0639\u062a \u0623\u0628\u0627 \u0628\u0643\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u062a\u0644\u0627\u0647\u0627 \u0641\u0639\u0642\u0631\u062a - \u0633\u0642\u0637\u062a - \u062d\u062a\u0649 \u0645\u0627\u062a\u0642\u0644\u0646\u064a \u0631\u062c\u0644\u0627\u064a \u0648\u062d\u062a\u0649 \u0623\u0647\u0648\u064a\u062a \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u062d\u064a\u0646 \u0633\u0645\u0639\u062a\u0647 \u062a\u0644\u0627\u0647\u0627 \u0639\u0644\u0645\u062a \u0623\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0642\u062f \u0645\u0627\u062a.",null)
